package com.alpharip.staffmod.IncidentPostMortemBoard; import java.util.UUID; public final class IncidentAction { private String id,title,description,assignee; private boolean completed; private long createdAt,completedAt; public IncidentAction(){} public IncidentAction(String t,String d,String a,long n){id=UUID.randomUUID().toString();if(t==null||t.trim().isEmpty())throw new IllegalArgumentException("Action title required");title=t.trim();description=clean(d);assignee=clean(a);if(n<=0)throw new IllegalArgumentException("Timestamp must be positive");createdAt=n;} public String getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public String getAssignee(){return assignee;} public boolean isCompleted(){return completed;} public long getCreatedAt(){return createdAt;} public long getCompletedAt(){return completedAt;} public void setCompleted(boolean v,long n){if(n<=0)throw new IllegalArgumentException("Timestamp must be positive");completed=v;completedAt=v?n:0L;} public void assign(String s){assignee=clean(s);} private static String clean(String s){return s==null?"":s.trim();} }